fn is_prime(n: i8) -> bool {
    // By definition, primes are integers >= 2.
    if n < 2 {
        return false;
    }

    // Now we can safely work with n as a positive integer.
    let n_i32 = n as i32;

    // Check candidate divisors k in increasing order: 2 <= k < n.
    let mut k: i32 = 2;
    while k < n_i32 {
        // If any divisor is found, n is not prime.
        if n_i32 % k == 0 {
            return false;
        }

        // Termination measure example: (n - k) strictly decreases as k increases.
        k += 1;
    }

    // No divisors in [2, n) => prime by the given definition.
    true
}